function musicPanel(){var count=window.ReedMusicCatalog?window.ReedMusicCatalog.tracks.length:100;return '<div class="music-panel"><small>正在聆听 · ConcernedApe</small><strong id="music-now"></strong><p id="music-status" role="status"></p><div class="music-modes">'+[['auto','随环境'],['shuffle','随机播放'],['single','单曲循环']].map(function(m){return '<button data-action="music-mode-'+m[0]+'" data-music-mode="'+m[0]+'">'+m[1]+'</button>';}).join('')+'</div><div class="music-transport"><button data-action="music-previous" aria-label="上一首音乐">‹ 上一首</button><button data-action="music-library">曲库 · '+count+'首</button><button data-action="music-next" aria-label="下一首音乐">下一首 ›</button></div></div>';}
function syncMusicHUD(info){if(!state||!state.settings)return;info=info||(window.ReedAudio.getStatus?window.ReedAudio.getStatus():{});var title=document.getElementById('music-now'),status=document.getElementById('music-status');if(title)title.textContent=info.musicTitle||(window.ReedMusic&&window.ReedMusic.title)||'背景音乐';if(status)status.textContent=!prefs().bgm?'背景音乐已关闭':prefs().musicVolume===0?'音乐音量为0':info.musicError?'暂时未能播放，点下一首重试':info.musicLoading?'正在加载这一首…':(info.musicMode==='auto'?(info.musicScene||'随环境选曲')+' · ':info.musicMode==='shuffle'?'完整曲库随机播放 · ':'单曲循环 · ')+(info.musicPlaying?'播放中':'触摸后播放');Array.prototype.forEach.call(document.querySelectorAll('[data-music-mode]'),function(b){var on=b.dataset.musicMode===(prefs().musicMode||'auto');b.classList.toggle('chosen',on);b.setAttribute('aria-pressed',String(on));});Array.prototype.forEach.call(document.querySelectorAll('[data-music-id]'),function(b){var on=b.dataset.musicId===info.musicId;b.classList.toggle('playing',on);b.setAttribute('aria-pressed',String(on));});}
