function settingsModal(){if(!idleOnly())return;var p=prefs();modal('<h2 id="modal-title">设置</h2><p class="settings-intro">把水边，调成你喜欢的样子。</p>'+settingSwitch('bgm','背景音乐','16首精选原声节选 · ConcernedApe',p.bgm)+musicPanel()+settingRange('musicVolume','音乐音量',p.musicVolume)+settingSwitch('sound','游戏音效','抛竿、落水、咬钩与提竿提示',state.sound)+settingRange('sfxVolume','音效音量',p.sfxVolume)+settingSwitch('effects','装饰动效','水波、天气与镜头缓动；保留必要操作反馈',p.effects)+settingSwitch('vibration','触感反馈','蓄力与咬钩提示，支持震动的设备上生效',p.vibration)+kingMemoryCard()+'<button class="wide-link" data-action="learn-touch">重新练习触屏钓鱼</button><button class="wide-link" data-action="welcome-title">返回欢迎页</button><div class="settings-storage"><strong>本机存档</strong><p id="settings-save-state">'+(storageReadFailed?'读取失败，当前进度临时保留':lastSaved?'已读取本机存档 · 游戏进度自动保存':'自动保存已开启')+'</p><small>金币、鱼获、图鉴、装备和设置都会保存。<br>使用同一设备与入口继续；清理数据后需用备份恢复。</small><div class="modal-actions"><button class="secondary" data-action="save-now">立即保存</button><button class="primary" data-action="backup">备份与恢复</button></div></div>');syncMusicHUD();}
