function startSmoke(i){var f=state.bag[i];if(!state.smoker||state.smokeJob||!state.coal||!f||f.smoked)return;state.coal--;state.smokeJob={fish:state.bag.splice(i,1)[0],ready:EQ.now(state)+50};closeModal();render();save();toast('开始熏制，50分钟后到工坊取出。');}
function sellStack(f){var sum=0;state.bag=state.bag.filter(function(n){if(n.id===f.id&&n.quality===f.quality&&!!n.smoked===!!f.smoked){sum+=EQ.sellValue(state,n);return false;}return true;});state.coins+=sum;state.ledger.earned+=sum;render();save();toast('出售获得'+sum+'金币。');}

