function drawScene(t){if(!prefs().effects)t=0;var c=ctx,vw=Math.min(960,580*canvas.width/canvas.height),target=castLanding||landFor(state,phase==='charging'?castPower:1),stand=WORLD.spot(state),sx=stand.x*32+16,sy=stand.y*32+16,active=['casting','waiting','bite','hooking','fishing','retracting'].indexOf(phase)>=0,focus=state.home?420:active&&target?(sx+target.x)/2:sx,desired=clamp(focus-vw*.5,0,Math.max(0,960-vw));if(!sceneGesture.active())cameraPan+=(desired-cameraPan)*(prefs().effects ? .13:1);lastCameraX=cameraPan;lastWorldWidth=vw;c.save();c.scale(canvas.width/vw,canvas.height/580);c.translate(-cameraPan,0);
if(state.home){WORLD.drawHome(c,state,t);c.save();c.translate(75,70);var homePose=window.ReedMotion.pose('idle',0,0,0,2);window.ReedMotion.drawAngler(c,homePose);c.restore();}else{WORLD.draw(c,state.pool,state,t,false);var bubble=MECH.bubbles(state);if(bubble){for(var j=0;j<5;j++){var age=(t*.8+j*.2)%1;window.ReedMotion.ring(c,bubble.x+Math.sin(j*2)*14,bubble.y+Math.cos(j*3)*6-age*7,3+age*5,.6-age*.3);}}
if(phase==='charging'&&target){c.save();c.setLineDash([5,7]);c.strokeStyle='#fff4b6';c.lineWidth=2;c.beginPath();c.moveTo(sx,sy);c.lineTo(target.x,target.y);c.stroke();c.restore();}if((phase==='idle'||phase==='charging')&&target){c.strokeStyle='#f8e5abbb';c.lineWidth=2;c.strokeRect(target.tile.x*32+2,target.tile.y*32+2,28,28);pixel(c,target.x-2,target.y-2,4,4,'#fcebb7');}
var ox=sx-256,oy=sy-250;c.save();c.translate(ox,oy);var animPhase=phase==='retracting'?'hooking':phase,animAge=phase==='casting'?castAge:phase==='retracting'?retractAge:hookAge,pose=window.ReedMotion.pose(animPhase,animAge,castPower,standing,state.facing);window.ReedMotion.drawAngler(c,pose);window.ReedMotion.drawRod(c,pose,['#d0a04b','#d96740','#9b68d5','#b66af0','#80a95a'][state.rod]);
if(target){var bx=target.x-ox,by=target.y-oy,end={x:bx,y:by},waterActive=phase==='waiting'||phase==='bite'||phase==='fishing';if(phase==='casting'){if(castAge>=window.ReedMotion.timing.launch&&castAge<window.ReedMotion.timing.land){var point=window.ReedMotion.flight(castAge,castPosition,end,state.facing);window.ReedMotion.drawLine(c,pose,point,12+18*point.progress);window.ReedMotion.drawBobber(c,point.x,point.y,false);}else if(castAge>=window.ReedMotion.timing.land){window.ReedMotion.drawLine(c,pose,end,14);window.ReedMotion.drawBobber(c,bx,by,false);}}
if(waterActive){var bob=Math.sin(t*3.2)*1.8,dip=phase==='bite'?Math.min(1,biteAge/.12)*11+Math.sin(biteAge*26)*2:0;window.ReedMotion.drawLine(c,pose,{x:bx,y:by+bob+dip},phase==='bite'?0:12);window.ReedMotion.ring(c,bx,by+4,11+(t%1.6)*9,.42*(1-t%1.6/1.6));window.ReedMotion.drawBobber(c,bx,by+bob+dip,phase==='bite');if(phase==='bite')window.ReedMotion.drawBite(c,256,248-15*pose.stand,biteAge);}
if(phase==='hooking'||phase==='retracting'){var lift=Math.min(1,animAge/.34),point={x:bx+(pose.tip.x-bx)*lift*.6,y:by+(pose.tip.y-by)*lift};window.ReedMotion.drawLine(c,pose,point,0);window.ReedMotion.drawBobber(c,point.x,point.y,false);}}
c.restore();if(WORLD.drawForeground)WORLD.drawForeground(c,state.pool,state,t);if(phase==='charging'&&target){var aimAge=(sceneTime%1);window.ReedMotion.ring(c,target.x,target.y,12+aimAge*8,.8-aimAge*.4);}if(prefs().effects)waterEffects.forEach(function(e){window.ReedMotion.drawSplash(c,e);});
var weather=RULES.weather(state,POOLS[state.pool]);if(['rain','storm','green'].indexOf(weather)>=0){c.strokeStyle=weather==='green'?'#c1e9a266':'#d2e9db66';c.lineWidth=1;for(var i=0;i<(weather==='storm'?90:55);i++){var xx=(seeded(i)*1100-t*42)%1060,yy=(seeded(i+1)*700+t*120)%650;c.beginPath();c.moveTo(xx,yy);c.lineTo(xx-4,yy+11);c.stroke();}}if(weather==='snow'||weather==='wind'){for(var i=0;i<36;i++){var xx=(seeded(i)*1000+Math.sin(t*.3+i)*10)%960,yy=(seeded(i+4)*600+t*(weather==='snow'?16:8))%580;pixel(c,xx,yy,weather==='snow'?3:5,3,weather==='snow'?'#e9f0daaa':'#c7b07799');}}}
var dark=state.minutes<420 ? .1:state.minutes<1020?0:state.minutes<1140?(state.minutes-1020)/120*.2:state.minutes<1380 ? .22:.36;if(dark>0)pixel(c,0,0,960,580,'rgba(22,29,61,'+dark+')');if(state.minutes<420)pixel(c,0,0,960,580,'#f4d18c14');c.restore();if(!$('coach-marker').hidden&&target){$('coach-marker').style.left=clamp((target.x-lastCameraX)/lastWorldWidth*100,6,94)+'%';$('coach-marker').style.top=clamp(target.y/580*100,20,88)+'%';}}

var focused=true;window.addEventListener('blur',function(){focused=false;});window.addEventListener('focus',function(){focused=true;lastFrame=0;if(!paused)window.ReedAudio.setActive(true);});
function frame(time){var dt=lastFrame?Math.min((time-lastFrame)/1000,.1):0;lastFrame=time;if(!startupOpen&&!document.hidden&&focused&&!paused){sceneTime+=dt;if(sceneGesture.active())sceneGesture.tick(time);if($('modal').hidden&&!tutorialActive()&&!(fishGame&&fishGame.kingTrial)){tickBuff(dt);}if($('modal').hidden){tickLife(dt);tickPresentation(dt);tickWaiting(dt);tickGame(dt);}if($('modal').hidden&&$('game-overlay').hidden&&sceneTime-lastDraw>=1/30&&(mobileView==='home'||!isMobileLayout())){drawScene(sceneTime);lastDraw=sceneTime;}if(phase==='charging'){if(!sceneGesture.active())castPower=clamp((time-castStart)/900,0,1);}}requestAnimationFrame(frame);}
